export interface RecoverySessionStateEnvelope extends ProtocolEnvelopeBase {
  family: "recovery";
  type: "session_state";
  payload: {
    "diagnostics": unknown;
    "generation": unknown;
    "state": unknown;
  };
}


export interface RecoveryStoreStateEnvelope extends ProtocolEnvelopeBase {
  family: "recovery";
  type: "store_state";
  payload: {
    "diagnostics": unknown;
    "schema_version": unknown;
    "state": unknown;
  };
}

export type RecoveryEnvelope = RecoveryContinuityModeEnvelope | RecoverySessionStateEnvelope | RecoveryStoreStateEnvelope;


export interface RejectionSensitiveResultBlockedEnvelope extends ProtocolEnvelopeBase {
  family: "rejection";
  type: "sensitive_result_blocked";
  payload: {
    "operation_id": unknown;
    "phase": unknown;
    "reason": unknown;
    "redacted_details": unknown;
    "surface": unknown;
  };
}


export interface RejectionSensitiveValueRejectedEnvelope extends ProtocolEnvelopeBase {
  family: "rejection";
  type: "sensitive_value_rejected";
  payload: {
    "operation_id": unknown;
    "phase": unknown;
    "reason": unknown;
    "redacted_details": unknown;
    "surface": unknown;
  };
}

export type RejectionEnvelope = RejectionSensitiveResultBlockedEnvelope | RejectionSensitiveValueRejectedEnvelope;


export interface ReplayEventSuffixEnvelope extends ProtocolEnvelopeBase {
  family: "replay";
  type: "event_suffix";
  payload: {
    "after_sequence"?: unknown;
    "events"?: unknown;
  };
}


export interface ReplayReplayRequestEnvelope extends ProtocolEnvelopeBase {
  family: "replay";
  type: "replay_request";
  payload: {
    "after_sequence"?: unknown;
    "client_id"?: unknown;
  };
}

export type ReplayEnvelope = ReplayEventSuffixEnvelope | ReplayReplayRequestEnvelope;


export interface ResponseAcceptedEnvelope extends ProtocolEnvelopeBase {
  family: "response";
  type: "accepted";
  payload: {
    "reason"?: unknown;
    "ref_id"?: unknown;
  };
}


export interface ResponseDeferredEnvelope extends ProtocolEnvelopeBase {
  family: "response";
  type: "deferred";
  payload: {
    "reason"?: unknown;
    "ref_id"?: unknown;
  };
}


export interface ResponseRejectedEnvelope extends ProtocolEnvelopeBase {
  family: "response";
  type: "rejected";
  payload: {
    "reason"?: unknown;
    "ref_id"?: unknown;
  };
}

export type ResponseEnvelope = ResponseAcceptedEnvelope | ResponseDeferredEnvelope | ResponseRejectedEnvelope;


export interface SnapshotSessionSnapshotEnvelope extends ProtocolEnvelopeBase {
  family: "snapshot";
  type: "session_snapshot";
  payload: {
    "protocol_version"?: unknown;
    "sequence"?: unknown;
    "state"?: unknown;
  };
}

export type SnapshotEnvelope = SnapshotSessionSnapshotEnvelope;


export interface WatermarkConsoleJidokaEnvelope extends ProtocolEnvelopeBase {
  family: "watermark";
  type: "console_jidoka";
  payload: {
    "console_chain_digest": unknown;
    "console_event_id": unknown;
    "console_sequence": unknown;
    "durable_schema_version": unknown;
    "generation": unknown;
    "jidoka_lease_id": unknown;
    "jidoka_request_id": unknown;
    "jidoka_revision": unknown;
    "jidoka_session_id": unknown;
    "jidoka_snapshot_id": unknown;
    "jidoka_value_digest": unknown;
    "protocol_version": unknown;
    "state": unknown;
    "watermark_id": unknown;
  };
}

export type WatermarkEnvelope = WatermarkConsoleJidokaEnvelope;

export type ProtocolEnvelope = CommandEnvelope | ControlEnvelope | DeliveryEnvelope | EventEnvelope | GenerationEnvelope | InteractionEnvelope | OperationEnvelope | OutcomeEnvelope | ReceiptEnvelope | RecoveryEnvelope | RejectionEnvelope | ReplayEnvelope | ResponseEnvelope | SnapshotEnvelope | WatermarkEnvelope;

export function knownType(family: string, type: string): boolean {
  const entry = (protocolFamilies as Record<string, { types: Record<string, unknown> }>)[family];
  return Boolean(entry && entry.types && type in entry.types);
}
